pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut pairs: Vec<(i64, i64)> = Vec::new();

    if let serde_json::Value::Array(array) = input {
        for item in array {
            if let serde_json::Value::Array([key_val, val_val]) = item {
                if let Ok(key) = key_val.as_i64() {
                    if let Ok(val) = val_val.as_i64() {
                        pairs.push((key, val));
                    }
                }
            }
        }
    }

    pairs.sort_by(|a, b| {
        if a.0 == b.0 {
            a.1.cmp(&b.1)
        } else {
            a.0.cmp(&b.0)
        }
    });

    let mut result = Vec::new();
    for (key, val) in pairs {
        result.push(vec![key as i64, val as i64]);
    }

    serde_json::to_value(result).unwrap()
}
